mapper.select:
select id, revision, title, LEFT(regexp_replace(content, '<[^>]+>', ''), 300) content, folder, `order`, del_flag, version, client_uuid, create_by, create_time, update_by, update_time, remark from px_note
del_flag = 0
and folder = #{folder}
and (title like concat('%', #{title}, '%') or content like concat('%', #{title}, '%'))
and version = #{version}
and create_by = #{createBy}
ORDER BY (`order` is null or `order` = 0) ,`order`, update_time DESC

